INSERT INTO `v1_7807a18db5be33e2aeaa0bc4dc0052433b63124dc58fcf7296c9d881e4482f4c` VALUES (3, 3001, "vo_minigame_1012_result_1084", 1, 0, 5, 1, "はいお疲れ～\n点数的にはまあまあってとこね！\nま、超難問だし頑張ったわよ", 2, 4.19, 12300152, 7, 9);
